define([],function(){"use strict";var loadedAttribute="data-flw-video-loaded";function loadVideo(video){if(!video||video.getAttribute(loadedAttribute)==="1"){return}var changed=false;Array.prototype.slice.call(video.querySelectorAll("source[data-src]")).forEach(function(source){if(!source.getAttribute("src")){source.setAttribute("src",source.getAttribute("data-src"));changed=true}});if(changed){video.setAttribute(loadedAttribute,"1");video.load()}}function init(root){var container=root||document;var videos=Array.prototype.slice.call(container.querySelectorAll(".flw-video-hub video"));if(!videos.length){return}if(!("IntersectionObserver" in window)){videos.forEach(loadVideo);return}var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting){return}loadVideo(entry.target);observer.unobserve(entry.target)})},{rootMargin:"220px 0px",threshold:.01});videos.forEach(function(video){observer.observe(video)})}return{init:init}});
